def _receipt_index_hash(
    generation: int, finalized: dict, items: list[dict]
) -> str:
    """SHA-256 over the canonical JSON bytes of every field but ``hash``."""
    body = {
        "v": RECEIPT_INDEX_VERSION,
        "generation": generation,
        "finalized": finalized,
        "items": items,
    }
    return hashlib.sha256(_canonical_json_bytes(body)).hexdigest()


def _validate_receipt_index_shape(data: object) -> dict:
    """Strictly validate one version-1 receipt index document.

    Exact top-level key order ``v, generation, finalized, items, hash``;
    ``v`` must be 1 and ``generation`` a positive plain integer; the
    finalized boundary uses the closed ``{height, block_hash}`` shape;
    items must be ascending by ``tx_id`` with no duplicates and each item
    must satisfy the exact ``receipt, proof`` contract shapes. Beyond the
    shape, every item is revalidated against its own semantics: the
    receipt is confirmed, its ``tx_id`` is recomputed from ``(from, to,
    amount)`` and its Ed25519 signature verified, receipt and proof agree
    on height/tx_id/index/block_hash, and the proof's sibling path replays
    to its ``merkle_root`` under the ledger pairing and odd-node rules.
    The recorded ``hash`` is recomputed over the other fields last. A
    re-sealed file that merely carries a fresh hash over tampered content
    is still corruption; any defect is existing-state corruption.
    """
    if not isinstance(data, dict) or tuple(data.keys()) != RECEIPT_INDEX_KEYS:
        raise _CheckpointError(ERR_STATE)
    if not _is_int(data["v"]) or data["v"] != RECEIPT_INDEX_VERSION:
        raise _CheckpointError(ERR_STATE)
    generation = data["generation"]
    if not _is_int(generation) or generation < 1:
        raise _CheckpointError(ERR_STATE)
    raw_finalized = data["finalized"]
    if (
        not isinstance(raw_finalized, dict)
        or tuple(raw_finalized.keys()) != HEADER_ANCHOR_KEYS
    ):
        raise _CheckpointError(ERR_STATE)
    if not _is_int(raw_finalized["height"]) or raw_finalized["height"] < 0:
        raise _CheckpointError(ERR_STATE)
    if not crypto.is_hex64(raw_finalized["block_hash"]):
        raise _CheckpointError(ERR_STATE)
    finalized = {
        "height": raw_finalized["height"],
        "block_hash": raw_finalized["block_hash"],
    }
    raw_items = data["items"]
    if not isinstance(raw_items, list):
        raise _CheckpointError(ERR_STATE)
    items: list[dict] = []
    seen: set[str] = set()
    previous_id: str | None = None
    for raw_item in raw_items:
        if (
            not isinstance(raw_item, dict)
            or tuple(raw_item.keys()) != FINALIZED_RECEIPT_ITEM_KEYS
        ):
            raise _CheckpointError(ERR_STATE)
        try:
            receipt = _parse_finalized_receipt_receipt(raw_item["receipt"])
            proof = _parse_finalized_receipt_proof(raw_item["proof"])
        except _Failure as failure:
            raise _CheckpointError(ERR_STATE) from failure
        tx_id = receipt["tx_id"]
        if tx_id in seen or (previous_id is not None and tx_id < previous_id):
            raise _CheckpointError(ERR_STATE)
        seen.add(tx_id)
        previous_id = tx_id
        # Semantic revalidation independent of the recorded hash: a
        # re-sealed file with a freshly recomputed hash over tampered
        # items must still be rejected. The receipt is confirmed, its
        # tx_id is recomputed and its Ed25519 signature verified, receipt
        # and proof agree on height/tx_id/index/block_hash, and the
        # sibling path replays to the proof's merkle_root.
        try:
            _receipt_item_self_consistent(receipt, proof)
            _replay_proof_siblings(proof)
        except _Failure as failure:
            raise _CheckpointError(ERR_STATE) from failure
        items.append({"receipt": receipt, "proof": proof})
    digest = data["hash"]
    if not crypto.is_hex64(digest):
        raise _CheckpointError(ERR_STATE)
    if _receipt_index_hash(generation, finalized, items) != digest:
        raise _CheckpointError(ERR_STATE)
    return {
        "v": RECEIPT_INDEX_VERSION,
        "generation": generation,
        "finalized": finalized,
        "items": items,
        "hash": digest,
    }


def _load_receipt_index(path: str) -> dict | None:
    """Strictly load the receipt index at ``path`` (None when absent).

    An unreadable file is ``io``; bad UTF-8, malformed JSON and every
    shape/key-order/ordering/digest or per-item semantic defect is
    ``state`` (a re-sealed file whose hash matches its tampered content
    still fails the per-item checks). The file is never truncated or
    rebuilt.
    """
    try:
        with open(path, "r", encoding="utf-8") as fh:
            text = fh.read()
    except FileNotFoundError:
        return None
    except UnicodeDecodeError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    except OSError as exc:
        raise _CheckpointError(ERR_IO) from exc
    try:
        data = json.loads(text)
    except ValueError as exc:
        raise _CheckpointError(ERR_STATE) from exc
    return _validate_receipt_index_shape(data)


def _atomic_write_receipt_index(path: str, index: dict) -> None:
    """Write the index in declared key order and atomically replace ``path``."""
    ordered = {key: index[key] for key in RECEIPT_INDEX_KEYS}
    _atomic_write_bytes(path, _serialize_document(ordered))

def merkle_root(tx_ids: list[str]) -> str:
    """SHA-256 Merkle root of the given tx ids.

    Levels are built by hashing ``sha256(left + right)`` hex-string pairs;
    a lone odd node at a level is promoted by pairing it with itself.
    Callers normally pass ids already sorted ascending.
    """
    if not tx_ids:
        return EMPTY_MERKLE_ROOT
    level = list(tx_ids)
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
    return level[0]


# A SHA-256 digest rendered as 64 lowercase hexadecimal characters.
_HEX64_RE = re.compile(r"[0-9a-f]{64}")

# A 64-byte Ed25519 signature rendered as 128 lowercase hex characters.
_HEX128_RE = re.compile(r"[0-9a-f]{128}")

# Maximum Merkle depth we accept: 64 sibling levels already cover trees with up
# to 2**64 leaves, so a longer sibling path is necessarily malformed.
MAX_MERKLE_DEPTH = 64


def _is_hex64(value: object) -> bool:
    return isinstance(value, str) and _HEX64_RE.fullmatch(value) is not None


def is_hex64(value: object) -> bool:
    """True iff ``value`` is a 64-char lowercase SHA-256 hex string."""
    return _is_hex64(value)


def is_hex128(value: object) -> bool:
    """True iff ``value`` is a 128-char lowercase Ed25519 signature hex string."""
    return isinstance(value, str) and _HEX128_RE.fullmatch(value) is not None


def merkle_proof(tx_ids: list[str], index: int) -> list[dict]:
    """Sibling path from the leaf at ``index`` up to the Merkle root.

    Mirrors :func:`merkle_root`: levels hash ``sha256(left + right)`` hex pairs
    and a lone odd node is paired with itself. Each returned item has a
    ``direction`` ("left" or "right") recording which side the *sibling* sits
    on relative to the path node, and the sibling's ``hash``. Items are ordered
    from the leaf level toward the root. Raises ValueError for an empty list or
    an out-of-range index.
    """
    if not tx_ids:
        raise ValueError("cannot build a Merkle proof for an empty tree")
    if isinstance(index, bool) or not isinstance(index, int):
        raise ValueError("index must be an integer")
    if index < 0 or index >= len(tx_ids):
        raise ValueError("transaction index out of range")

    level = list(tx_ids)
    position = index
    siblings: list[dict] = []
    while len(level) > 1:
        if len(level) % 2 == 1:
            level.append(level[-1])
        if position % 2 == 0:
            # Path node is the left child; sibling sits on its right.
            siblings.append({"direction": "right", "hash": level[position + 1]})
        else:
            # Path node is the right child; sibling sits on its left.
            siblings.append({"direction": "left", "hash": level[position - 1]})
        level = [
            sha256_hex((level[i] + level[i + 1]).encode("ascii"))
            for i in range(0, len(level), 2)
        ]
        position //= 2
    return siblings


